const wrap=(ctx,text,max)=>{const result=[];let line='';for(const word of String(text).trim().split(/\s+/)){const next=line?line+' '+word:word;if(line&&ctx.measureText(next).width>max){result.push(line);line=word}else line=next}if(line)result.push(line);return result};
function imageCover(ctx,image,w,h){const iw=image.naturalWidth||image.width,ih=image.naturalHeight||image.height;if(!iw||!ih)return;const r=Math.max(w/iw,h/ih);ctx.drawImage(image,(w-iw*r)/2,(h-ih*r)/2,iw*r,ih*r)}
export function drawDesignedCover(ctx,canvas,source,s,logo){const w=canvas.width,h=canvas.height;if(s.generatedImage&&source){ctx.save();ctx.fillStyle='#111';ctx.fillRect(0,0,w,h);imageCover(ctx,source,w,h);ctx.restore();return}const short=Math.min(w,h),pad=w*.07,split=['split','diagonal','sidebar'].includes(s.layout),center=s.align==='center'||['spotlight','cinema'].includes(s.layout);ctx.save();ctx.fillStyle='#181818';ctx.fillRect(0,0,w,h);if(source)imageCover(ctx,source,w,h);if(s.shade){ctx.fillStyle=`rgba(0,0,0,${s.shade*.55})`;ctx.fillRect(0,0,w,h)}if(s.layout==='cinema'){ctx.fillStyle='#080808';ctx.fillRect(0,0,w,h*.075);ctx.fillRect(0,h*.925,w,h*.075)}if(s.layout==='magazine'){ctx.strokeStyle=s.accent;ctx.lineWidth=short*.012;ctx.strokeRect(pad*.5,h*.035,w-pad,h*.93)}if(s.layout==='minimal'){ctx.fillStyle='rgba(0,0,0,.32)';ctx.fillRect(0,0,w,h)}if(s.layout==='spotlight'){const light=ctx.createRadialGradient(w*.5,h*.35,short*.15,w*.5,h*.4,short*.9);light.addColorStop(0,'#00000000');light.addColorStop(1,'#000000bd');ctx.fillStyle=light;ctx.fillRect(0,0,w,h)}const maxWidth=s.layout==='sidebar'?w*.62:w-pad*2;let fs=short*s.textSize/100;const top=s.layout==='magazine'?h*.1:s.layout==='minimal'?h*.74:s.layout==='spotlight'?h*.7:s.position==='top'?h*.11:s.position==='center'?h*.39:h*.67,area=split?h*.35:Math.min(h*.33,h-top-h*.07);if(split){if(s.gradient){const panel=ctx.createLinearGradient(0,h*.62,w,h);panel.addColorStop(0,s.accent);panel.addColorStop(1,'#fff4da');ctx.fillStyle=panel}else ctx.fillStyle=s.accent;if(s.layout==='diagonal'){ctx.beginPath();ctx.moveTo(0,h*.59);ctx.lineTo(w,h*.68);ctx.lineTo(w,h);ctx.lineTo(0,h);ctx.closePath();ctx.fill()}else if(s.layout==='sidebar')ctx.fillRect(0,h*.48,w*.76,h*.52);else ctx.fillRect(0,h*.62,w,h*.38)}else{const gradient=ctx.createLinearGradient(0,Math.max(0,top-h*.15),0,Math.min(h,top+area+h*.07));gradient.addColorStop(0,'rgba(0,0,0,0)');gradient.addColorStop(.45,`rgba(0,0,0,${Math.min(.82,.35+s.shade)})`);gradient.addColorStop(1,s.gradient?s.gradientEnd:'rgba(0,0,0,.85)');ctx.fillStyle=gradient;ctx.fillRect(0,Math.max(0,top-h*.15),w,h)}let titleLines=[];for(let i=0;i<80;i++){ctx.font=`800 ${fs}px "${s.font}",sans-serif`;titleLines=wrap(ctx,s.title,maxWidth);if(titleLines.length<=4&&titleLines.length*fs*1.05<=area*.74)break;fs-=1;if(fs<short*.045)throw Error('Сократите заголовок: он не помещается крупно и читаемо.')}let y=s.layout==='sidebar'?h*.54:split?h*.69:top;if(s.layout==='editorial'&&!split){ctx.fillStyle=s.accent;ctx.fillRect(pad,y-short*.035,short*.16,short*.008)}ctx.textBaseline='top';ctx.textAlign=center?'center':'left';const x=center?w/2:pad;for(const [i,line]of titleLines.entries()){ctx.fillStyle=split?'#101010':i===titleLines.length-1?s.accent:'#fff';ctx.shadowColor='rgba(0,0,0,.6)';ctx.shadowBlur=split?0:fs*.12;ctx.fillText(line,x,y,maxWidth);y+=fs*1.04}ctx.shadowBlur=0;ctx.font=`500 ${Math.max(short*.027,fs*.29)}px "${s.font}",sans-serif`;ctx.fillStyle=split?'#222':'#efefef';y+=fs*.26;const subLines=wrap(ctx,s.subtitle,maxWidth);if(subLines.length>3)throw Error('Подзаголовок слишком длинный. Оставьте одну короткую мысль.');for(const line of subLines){ctx.fillText(line,x,y,maxWidth);y+=fs*.38}if(logo&&s.logo){const r=Math.min(short*.12/logo.width,short*.12/logo.height);ctx.drawImage(logo,w-pad-logo.width*r,h*.055,logo.width*r,logo.height*r)}ctx.restore()}
export function frameQuality(data){let mean=0,square=0,edges=0;const values=[];for(let i=0;i<data.length;i+=4){const v=(data[i]*.2126+data[i+1]*.7152+data[i+2]*.0722)/255;values.push(v);mean+=v;square+=v*v}mean/=values.length;square/=values.length;for(let i=1;i<values.length;i++)edges+=Math.abs(values[i]-values[i-1]);return Math.max(0,1-Math.abs(mean-.52)*1.7)*.45+Math.sqrt(Math.max(0,square-mean*mean))*.3+edges/values.length*.25}
